library;

export 'src/metadata.dart';
export 'media_metadata_platform_interface.dart';
export 'media_metadata_method_channel.dart';

import 'media_metadata_platform_interface.dart';
import 'src/metadata.dart';

/// Main entry-point for the media_metadata plugin.
///
/// Usage:
/// ```dart
/// final metadata = await MediaMetadata.read('/path/to/file.mp3');
/// print(metadata?.title);
/// print(metadata?.imageMetadata?.data);
/// ```
class MediaMetadata {
  MediaMetadata._();

  /// Supported file extensions.
  static const List<String> supportedExtensions = [
    // Vidéos
    'mp4', 'mkv', '3gp', '3gpp', 'mov',
    // Audio (géré spécifiquement)
    'mp3',
    // Images
    'jpg', 'jpeg', 'png', 'heic', 'webp', 'tiff', 'gif', 'bmp'
  ];

  /// Reads the metadata from the file at [filePath].
  ///
  /// If [createThumbnail] is `true` and [filePath] is a video file with no
  /// real embedded cover art, a thumbnail is generated by capturing a frame
  /// from the video itself (similar to what a file explorer or media player
  /// would show) — the same real content, never a generic file-type icon.
  /// When a thumbnail is generated this way,
  /// `metadata.imageMetadata.isGenerated` is `true` so callers can tell it
  /// apart from a genuine embedded cover. Defaults to `false`, since
  /// generating a thumbnail is more expensive than reading existing tags.
  ///
  /// Returns `null` if the file is unreadable or unsupported.
  /// Throws [ArgumentError] if [filePath] is empty.
  static Future<Metadata?> read(String filePath, {bool createThumbnail = false}) async {
    if (filePath.trim().isEmpty) {
      throw ArgumentError('filePath must not be empty');
    }
    return MediaMetadataPlatform.instance.readMetadata(
      filePath,
      createThumbnail: createThumbnail,
    );
  }

  /// Writes the metadata to the file at [filePath].
  ///
  /// Returns `true` if the write succeeded. On unsupported platforms or when
  /// tags cannot be written, this returns `false`.
  /// Throws [ArgumentError] if [filePath] is empty.
  static Future<bool> write(String filePath, Metadata metadata) async {
    if (filePath.trim().isEmpty) {
      throw ArgumentError('filePath must not be empty');
    }
    return MediaMetadataPlatform.instance.writeMetadata(filePath, metadata);
  }

  /// Returns `true` if the file extension of [filePath] is supported.
  static bool isSupported(String filePath) {
    final ext = filePath.split('.').last.toLowerCase();
    return supportedExtensions.contains(ext);
  }
}
